int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, guint8 *drep, char **data, int hf_name) {
    int new_offset = offset;

    /* Ensure the offset is even */
    if (offset % 2 != 0) {
        new_offset++;
    }

    /* Get the length of the remaining data */
    int length = tvb_reported_length_remaining(tvb, new_offset);

    /* Get the UTF-16 string */
    char *utf16_str = tvb_get_ep_str(tvb, new_offset, length);

    /* Add the string to the protocol tree */
    proto_tree_add_string(tree, hf_name, tvb, new_offset, length, utf16_str);

    /* Update the data pointer if it is not NULL */
    if (data != NULL) {
        *data = utf16_str;
    }

    /* Update and return the new offset */
    new_offset += length;
    return new_offset;
}

