int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo _U_, proto_tree *tree, guint8 *drep _U_, char **data, int hf_name) {
    offset = (offset + 1) & (~1); /* Adjust offset to be even */
    int length = tvb_reported_length_remaining(tvb, offset);
    if (length <= 0) {
        return offset;
    }

    guint16 *string_utf16 = g_new(guint16, length / 2);
    tvb_get_utf16(tvb, offset, length, FALSE, FALSE, string_utf16, NULL);

    char *string = g_utf16_to_utf8(string_utf16, length / 2, NULL, NULL, NULL);
    if (string != NULL) {
        proto_tree_add_string(tree, hf_name, tvb, offset, length, string);
        if (data != NULL) {
            *data = string;
        } else {
            g_free(string);
        }
    }

    g_free(string_utf16);
    return offset + length;
}

int dissect_unicode_string(tvbuff_t *tvb, int offset, packet_info *pinfo, proto_tree *tree, guint8 *drep, char **data, int hf_name) {
    /* Adjust offset to be even */
    if (offset % 2 != 0) {
        offset++;
    }

    /* Retrieve the UTF-16 string from the tvbuff */
    guint16 string_length = tvb_reported_length_remaining(tvb, offset) / 2;
    const guint8 *raw_data = tvb_get_ptr(tvb, offset, string_length * 2);
    gsize out_len;
    gchar *utf8_string = g_utf16_to_utf8((gunichar2 *)raw_data, string_length, NULL, &out_len, NULL);

    /* Add the UTF-8 string to the protocol tree */
    if (tree) {
        proto_tree_add_string(tree, hf_name, tvb, offset, string_length * 2, utf8_string);
    }

    /* Update the data pointer if necessary */
    if (data) {
        *data = utf8_string;
    }

    /* Return the updated offset */
    return offset + string_length * 2;
}

